Tool response:
Tool: update_stop_status_and_reattempt_window
Description: Update Stop Status And Reattempt Window
Parameters:
    {
      "type": "object",
      "properties": {
        "route_code": {
          "type": "string",
          "description": "Unique identifier for the route",
          "title": "Route Code"
        },
        "stop_code": {
          "type": "string",
          "description": "Unique identifier for the stop",
          "title": "Stop Code"
        },
        "attempt_reason": {
          "type": "string",
          "title": "Attempt Reason",
          "description": "Reason for the stop attempt failure"
        },
        "reattempt_window_start": {
          "type": "string",
          "title": "Reattempt Window Start",
          "description": "Start time of the reattempt window in ISO 8601 format"
        },
        "reattempt_window_end": {
          "type": "string",
          "title": "Reattempt Window End",
          "description": "End time of the reattempt window in ISO 8601 format"
        }
      },
      "required": [
        "route_code",
        "stop_code",
        "attempt_reason",
        "reattempt_window_start",
        "reattempt_window_end"
      ]
    }

Tool response:
Tool: trigger_reroute_for_stop
Description: Trigger Reroute For Stop
Parameters:
    {
      "type": "object",
      "properties": {
        "route_code": {
          "type": "string",
          "description": "Unique identifier for the route",
          "title": "Route Code"
        },
        "stop_code": {
          "type": "string",
          "description": "Unique identifier for the stop that failed",
          "title": "Stop Code"
        }
      },
      "required": [
        "route_code",
        "stop_code"
      ]
    }
